import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.map.js";
import SnackBar from "@/components/SnackBar.vue";
export default {
  name: "WebsiteEdit",
  components: {
    SnackBar
  },
  data() {
    return {
      activeTab: 0,
      editableData: {
        sections: {
          navigation: {
            logo: "",
            links: []
          },
          hero: {
            title: "",
            subtitle: "",
            primaryButton: "",
            secondaryButton: "",
            image: ""
          },
          about: {
            title: "",
            description: "",
            image: ""
          },
          features: [],
          services: [],
          contact: {
            title: "",
            subtitle: "",
            submitButton: ""
          },
          footer: {
            logo: "",
            text: "",
            links: []
          }
        }
      },
      navigationLinksInput: "",
      footerLinksInput: "",
      heroImageUrl: "",
      SnackBarComponent: {},
      tabs: [{
        name: "Navigation",
        icon: "mdi-navigation"
      }, {
        name: "Hero Section",
        icon: "mdi-star"
      }, {
        name: "About",
        icon: "mdi-information"
      }, {
        name: "Features",
        icon: "mdi-feature-search"
      }, {
        name: "Services",
        icon: "mdi-cog"
      }, {
        name: "Contact",
        icon: "mdi-phone"
      }, {
        name: "Footer",
        icon: "mdi-page-layout-footer"
      }]
    };
  },
  computed: {
    websiteData() {
      const raw = this.$store.getters.GetGeneratedData;
      if (!raw) return null;
      if (raw.sections) return raw;
      if (raw.data && raw.data.sections) return raw.data;
      return null;
    }
  },
  mounted() {
    this.initializeEditMode();
  },
  methods: {
    goBack() {
      this.$router.push("/home/WebsiteDeploy");
    },
    initializeEditMode() {
      if (!this.websiteData) {
        this.$router.push("/WebSiteBuilder");
        return;
      }

      // Deep clone the website data for editing
      this.editableData = JSON.parse(JSON.stringify(this.websiteData));

      // Initialize navigation links input
      this.navigationLinksInput = this.websiteData.sections.navigation.links.join(", ");

      // Initialize footer links input
      this.footerLinksInput = this.websiteData.sections.footer.links.join(", ");

      // Initialize hero image URL
      this.heroImageUrl = this.websiteData.sections.hero.image || "";
    },
    saveChanges() {
      // Update navigation links
      this.editableData.sections.navigation.links = this.navigationLinksInput.split(",").map(link => link.trim()).filter(link => link.length > 0);

      // Update footer links
      this.editableData.sections.footer.links = this.footerLinksInput.split(",").map(link => link.trim()).filter(link => link.length > 0);

      // Update hero image URL
      this.editableData.sections.hero.image = this.heroImageUrl;

      // Update the Vuex store with edited data
      this.$store.commit("SetGeneratedData", this.editableData);

      // Show success message
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: "Website content updated successfully!",
        timeout: 3000
      };

      // Navigate back to deploy view
      setTimeout(() => {
        this.$router.push("/home/WebsiteDeploy");
      }, 1500);
    },
    addService() {
      this.editableData.sections.services.push({
        title: "New Service",
        description: "Service description",
        link: "Learn More",
        icon: "mdi-star"
      });
    },
    removeService(index) {
      this.editableData.sections.services.splice(index, 1);
    },
    addFeature() {
      this.editableData.sections.features.push({
        title: "New Feature",
        description: "Feature description",
        icon: "mdi-star"
      });
    },
    removeFeature(index) {
      this.editableData.sections.features.splice(index, 1);
    }
  }
};
